export function reconcileLedger(values: number[]): number {
  // Reconcile the ledger by summing all valid entries; non-finite
  // values (NaN/Infinity) are treated as 0 so they don't corrupt the total.
  return values.reduce(
    (total, value) => total + (Number.isFinite(value) ? value : 0),
    0
  );
}

